"""
CPA 注册会计师考试真题扩展题库（第二批）—— 会计与审计。

基于2020-2024年CPA考试大纲和历年真题考点编写，
覆盖会计科目（借贷记账法、会计要素、存货、固定资产、无形资产、投资性房地产、
长期股权投资、资产减值、负债、职工薪酬、借款费用、股份支付、或有事项、金融工具、
所有者权益、收入费用、政府补助、非货币性资产交换、债务重组、所得税、外币折算、
租赁、财务报告、现金流量表、资产负债表日后事项、企业合并、合并财务报表等）及
审计科目（审计概念与目标、审计计划、重要性、审计证据、审计程序、函证、分析程序、
审计抽样、审计工作底稿、风险评估、审计风险模型、风险应对、内部控制、各循环审计、
货币资金审计、舞弊与法律法规、完成审计工作、审计报告、内部控制审计、职业道德等）。

题目内容依据中国企业会计准则和中国注册会计师审计准则编写，
每题均附详细解析（explanation不少于50字）。
题型以 single_choice（单选题）为主，judgment（判断题）为辅。
文件末尾定义两个常量列表：ACCOUNTING_EXAMS_EXT2 与 AUDIT_EXAMS_EXT2。
"""

